	while (*start == ' ' || *start == '\t' || *start == '\n' || *start == '\r')
		start++;
	char *end = start + strlen(start);
	while (end > start &&
	       (end[-1] == ' ' || end[-1] == '\t' ||
	        end[-1] == '\n' || end[-1] == '\r'))
		end--;
	*end = '\0';

